"""
INSTALLATEUR CONSULTATION AI  (v1.14)

  python installer.py   puis   python main.py   |   python audit.py
  OU (sans ligne de commande) : double-clic sur lancer_gui.bat

v1.14 - CAUSE PROBABLE DE "la fenetre s'ouvre puis se ferme" :
  lancer_gui.bat etait ecrit avec des fins de ligne UNIX (LF) au lieu de
  WINDOWS (CRLF). cmd.exe casse la-dessus, en particulier sur les blocs
  entre parentheses "if errorlevel 1 ( ... )" : il peut avaler la ligne
  suivante et sortir immediatement, sans rien afficher. C'est coherent
  avec le fait que "python gui.py" depuis VS Code fonctionnait (VS Code
  n'utilise pas le .bat).
  Corrige :
   - lancer_gui.bat est desormais ecrit en CRLF, en ASCII pur (aucun
     accent, qui s'affiche mal et peut gener cmd), et SANS bloc entre
     parentheses (structure a base de "goto", la plus robuste).
   - Le lanceur "py -3" (installe avec Python depuis python.org) est
     essaye EN PREMIER : il evite le raccourci Microsoft Store qui, lui,
     ne fait rien quand on double-clique. Repli sur "python" ensuite.
   - Le .bat ecrit maintenant son propre journal : lancement.log
     (a cote du .bat), avec le dossier, l'interpreteur choisi, son chemin
     exact et le code de retour - meme si tout casse avant gui.py.
   - L'installeur force les fins de ligne CRLF pour tout fichier .bat.

v1.13 - Verification/installation auto des dependances (openpyxl, PyMuPDF)
  dans l'interpreteur qui execute reellement le script.
v1.12 - Diagnostic du lancement (gui_erreur.log).
v1.11 - Interface graphique (gui.py + lancer_gui.bat).
v1.10 - Chantiers nommes. v1.9 - Consolidation par coeur numerique.

14 fournisseurs. Depose ta base dans base/BDD_articles.csv.
"""

