DOSSIERS=['besoins','devis','resultats','base','moteur','moteur/fournisseurs']


def main():
    for d in DOSSIERS: os.makedirs(d, exist_ok=True)
    for chemin,b64 in FICHIERS.items():
        if 'exemple' in chemin and os.path.exists(chemin):
            print('= garde   ',chemin); continue
        d=os.path.dirname(chemin)
        if d: os.makedirs(d, exist_ok=True)
        donnees=base64.b64decode(b64)
        # Un fichier .bat DOIT avoir des fins de ligne Windows (CRLF) :
        # cmd.exe casse sur du LF seul (fenetre qui se ferme aussitot).
        if chemin.lower().endswith('.bat'):
            donnees=donnees.replace(b'\r\n',b'\n').replace(b'\n',b'\r\n')
        open(chemin,'wb').write(donnees)
        print('+ ecrit   ',chemin)
    print(); print('Installation terminee.')
    if not os.path.exists('base/BDD_articles.csv'):
        print('>> Depose ta base dans  base/BDD_articles.csv')
    print('Lance :  python main.py   |   Controle :  python audit.py')
    print('Sans ligne de commande :  double-clic sur lancer_gui.bat')


if __name__=='__main__': main()